    [HttpGet("settings")]
    public async Task<IActionResult> Settings(CancellationToken token){if(!Scope(out var c,out _))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47001","VIEW",token))return Forbid();var canCreate=await Allow(db,"47001","CREATE",token);var canEdit=await Allow(db,"47001","EDIT",token);var canDelete=await Allow(db,"47001","DELETE",token);var q=new SqlCommand("SELECT S.EvaluationSystemSettingID,S.SourceType,S.DefaultEvaluationTemplateID,T.TemplateName,S.IsActive FROM dbo.TDEVSystemSetting S LEFT JOIN dbo.TDEVTemplate T ON T.EvaluationTemplateID=S.DefaultEvaluationTemplateID AND T.CompanyID=S.CompanyID WHERE S.CompanyID=@c ORDER BY S.SourceType",db);q.Parameters.AddWithValue("@c",c);await using var r=await q.ExecuteReaderAsync(token);var items=new List<object>();while(await r.ReadAsync(token))items.Add(new{id=r.GetInt64(0),sourceType=r.GetString(1),templateId=r.IsDBNull(2)?(long?)null:r.GetInt64(2),templateName=r.IsDBNull(3)?null:r.GetString(3),isActive=r.GetBoolean(4)});return Ok(new{items,permissions=new{create=canCreate,edit=canEdit,delete=canDelete}});}
    [HttpPost("settings")]
