    [HttpPost("templates")]
    public async Task<IActionResult> CreateTemplate([FromBody]TemplateRequest request,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();var code=request.Code?.Trim().ToUpperInvariant();var name=request.Name?.Trim();var source=request.SourceType?.Trim().ToUpperInvariant();var qs=request.Questions??[];var types=new[]{"TRAINING_COURSE","TRAINING_INSTRUCTOR","MEETING_ROOM","VENDOR","SERVICE","GENERAL"};if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name)||!types.Contains(source)||qs.Count==0||qs.Any(q=>string.IsNullOrWhiteSpace(q.Text)||q.Type is not("RATING_5" or "SINGLE_CHOICE" or "MULTIPLE_CHOICE" or "TEXT")||((q.Type=="SINGLE_CHOICE"||q.Type=="MULTIPLE_CHOICE")&&(q.Options?.Count??0)<2)))return BadRequest(new{message="ข้อมูลแบบประเมินไม่ถูกต้อง",description="กรุณาระบุรหัส ชื่อ ประเภท และคำถามให้ครบ; คำถามแบบเลือกต้องมีอย่างน้อย 2 ตัวเลือก"});await using var db=await Open(token);if(!await Allow(db,"47002","CREATE",token))return Forbid();await using var tx=await db.BeginTransactionAsync(token);try{var parent=new SqlCommand("INSERT dbo.TDEVTemplate(CompanyID,TemplateCode,TemplateName,SourceType,CreateBy) OUTPUT INSERTED.EvaluationTemplateID VALUES(@c,@code,@name,@source,@u)",db,(SqlTransaction)tx);parent.Parameters.AddWithValue("@c",c);parent.Parameters.AddWithValue("@code",code);parent.Parameters.AddWithValue("@name",name);parent.Parameters.AddWithValue("@source",source);parent.Parameters.AddWithValue("@u",u);var id=Convert.ToInt64(await parent.ExecuteScalarAsync(token));foreach(var q in qs.OrderBy(x=>x.SortOrder)){var qc=new SqlCommand("INSERT dbo.TDEVTemplateQuestion(EvaluationTemplateID,CompanyID,QuestionText,QuestionType,IsRequired,SortOrder) OUTPUT INSERTED.EvaluationTemplateQuestionID VALUES(@id,@c,@text,@type,@required,@sort)",db,(SqlTransaction)tx);qc.Parameters.AddWithValue("@id",id);qc.Parameters.AddWithValue("@c",c);qc.Parameters.AddWithValue("@text",q.Text.Trim());qc.Parameters.AddWithValue("@type",q.Type);qc.Parameters.AddWithValue("@required",q.Type=="TEXT"?q.IsRequired:q.IsRequired);qc.Parameters.AddWithValue("@sort",q.SortOrder);var qid=Convert.ToInt64(await qc.ExecuteScalarAsync(token));foreach(var o in q.Options??[]) {var oc=new SqlCommand("INSERT dbo.TDEVTemplateQuestionOption(EvaluationTemplateQuestionID,OptionText,SortOrder) VALUES(@id,@text,@sort)",db,(SqlTransaction)tx);oc.Parameters.AddWithValue("@id",qid);oc.Parameters.AddWithValue("@text",o.Text.Trim());oc.Parameters.AddWithValue("@sort",o.SortOrder);await oc.ExecuteNonQueryAsync(token);}}await tx.CommitAsync(token);return Ok(new{id});}catch(SqlException e)when(e.Number is 2601 or 2627){await tx.RollbackAsync(token);return Conflict(new{message="รหัสแบบประเมินซ้ำ",description="กรุณาเปลี่ยนรหัสแบบประเมินแล้วบันทึกใหม่"});}}

    [HttpGet("templates/{id:long}")]
    public async Task<IActionResult> Template(long id,CancellationToken token){if(!Scope(out var c,out _))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47002","VIEW",token))return Forbid();var head=new SqlCommand("SELECT TemplateCode,TemplateName,SourceType FROM dbo.TDEVTemplate WHERE CompanyID=@c AND EvaluationTemplateID=@id",db);head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@id",id);await using var hr=await head.ExecuteReaderAsync(token);if(!await hr.ReadAsync(token))return NotFound();var code=hr.GetString(0);var name=hr.GetString(1);var source=hr.GetString(2);await hr.CloseAsync();var cmd=new SqlCommand("SELECT Q.EvaluationTemplateQuestionID,Q.QuestionText,Q.QuestionType,Q.IsRequired,Q.SortOrder,O.OptionText,O.SortOrder FROM dbo.TDEVTemplateQuestion Q LEFT JOIN dbo.TDEVTemplateQuestionOption O ON O.EvaluationTemplateQuestionID=Q.EvaluationTemplateQuestionID WHERE Q.CompanyID=@c AND Q.EvaluationTemplateID=@id ORDER BY Q.SortOrder,O.SortOrder",db);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@id",id);await using var r=await cmd.ExecuteReaderAsync(token);var questions=new Dictionary<long,Dictionary<string,object>>();while(await r.ReadAsync(token)){var questionId=r.GetInt64(0);if(!questions.TryGetValue(questionId,out var question)){question=new Dictionary<string,object>{{"text",r.GetString(1)},{"type",r.GetString(2)},{"isRequired",r.GetBoolean(3)},{"sortOrder",r.GetInt32(4)},{"options",new List<object>()}};questions.Add(questionId,question);}if(!r.IsDBNull(5))((List<object>)question["options"]).Add(new{text=r.GetString(5),sortOrder=r.GetInt32(6)});}return Ok(new{code,name,sourceType=source,questions=questions.Values.OrderBy(x=>(int)x["sortOrder"])});}

