    public async Task<IActionResult> UpdateTemplate(long id,[FromBody]TemplateRequest request,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();var code=request.Code?.Trim().ToUpperInvariant();var name=request.Name?.Trim();var source=request.SourceType?.Trim().ToUpperInvariant();var qs=request.Questions??[];var types=new[]{"TRAINING_COURSE","TRAINING_INSTRUCTOR","MEETING_ROOM","VENDOR","SERVICE","GENERAL"};if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name)||!types.Contains(source)||qs.Count==0||qs.Any(q=>string.IsNullOrWhiteSpace(q.Text)||q.Type is not("RATING_5" or "SINGLE_CHOICE" or "MULTIPLE_CHOICE" or "TEXT")||((q.Type=="SINGLE_CHOICE"||q.Type=="MULTIPLE_CHOICE")&&(q.Options?.Count??0)<2)))return BadRequest(new{message="ข้อมูลแบบประเมินไม่ถูกต้อง",description="กรุณาระบุรหัส ชื่อ ประเภท และคำถามให้ครบ; คำถามแบบเลือกต้องมีอย่างน้อย 2 ตัวเลือก"});await using var db=await Open(token);if(!await Allow(db,"47002","EDIT",token))return Forbid();await using var tx=await db.BeginTransactionAsync(token);try{var head=new SqlCommand("UPDATE dbo.TDEVTemplate SET TemplateCode=@code,TemplateName=@name,SourceType=@source,UpdateDate=SYSUTCDATETIME(),UpdateBy=@u WHERE CompanyID=@c AND EvaluationTemplateID=@id",db,(SqlTransaction)tx);head.Parameters.AddWithValue("@code",code);head.Parameters.AddWithValue("@name",name);head.Parameters.AddWithValue("@source",source);head.Parameters.AddWithValue("@u",u);head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@id",id);if(await head.ExecuteNonQueryAsync(token)!=1){await tx.RollbackAsync(token);return NotFound();}var clear=new SqlCommand("DELETE dbo.TDEVTemplateQuestion WHERE CompanyID=@c AND EvaluationTemplateID=@id",db,(SqlTransaction)tx);clear.Parameters.AddWithValue("@c",c);clear.Parameters.AddWithValue("@id",id);await clear.ExecuteNonQueryAsync(token);foreach(var q in qs.OrderBy(x=>x.SortOrder)){var qc=new SqlCommand("INSERT dbo.TDEVTemplateQuestion(EvaluationTemplateID,CompanyID,QuestionText,QuestionType,IsRequired,SortOrder) OUTPUT INSERTED.EvaluationTemplateQuestionID VALUES(@id,@c,@text,@type,@required,@sort)",db,(SqlTransaction)tx);qc.Parameters.AddWithValue("@id",id);qc.Parameters.AddWithValue("@c",c);qc.Parameters.AddWithValue("@text",q.Text.Trim());qc.Parameters.AddWithValue("@type",q.Type);qc.Parameters.AddWithValue("@required",q.IsRequired);qc.Parameters.AddWithValue("@sort",q.SortOrder);var questionId=Convert.ToInt64(await qc.ExecuteScalarAsync(token));foreach(var o in q.Options??[]){var oc=new SqlCommand("INSERT dbo.TDEVTemplateQuestionOption(EvaluationTemplateQuestionID,OptionText,SortOrder) VALUES(@id,@text,@sort)",db,(SqlTransaction)tx);oc.Parameters.AddWithValue("@id",questionId);oc.Parameters.AddWithValue("@text",o.Text.Trim());oc.Parameters.AddWithValue("@sort",o.SortOrder);await oc.ExecuteNonQueryAsync(token);}}await tx.CommitAsync(token);return Ok(new{id});}catch(SqlException e)when(e.Number is 2601 or 2627){await tx.RollbackAsync(token);return Conflict(new{message="รหัสแบบประเมินซ้ำ",description="กรุณาเปลี่ยนรหัสแบบประเมินแล้วบันทึกใหม่"});}}

    [HttpDelete("templates/{id:long}")]
    public async Task<IActionResult> DeleteTemplate(long id,CancellationToken token){if(!Scope(out var c,out _))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47002","DELETE",token))return Forbid();var used=new SqlCommand("SELECT COUNT_BIG(1) FROM dbo.TDEVRound WHERE CompanyID=@c AND EvaluationTemplateID=@id",db);used.Parameters.AddWithValue("@c",c);used.Parameters.AddWithValue("@id",id);if(Convert.ToInt64(await used.ExecuteScalarAsync(token))>0)return Conflict(new{message="ไม่สามารถลบแบบประเมิน",description="แบบประเมินนี้ถูกใช้สร้างรอบประเมินแล้ว"});var delete=new SqlCommand("DELETE dbo.TDEVTemplate WHERE CompanyID=@c AND EvaluationTemplateID=@id",db);delete.Parameters.AddWithValue("@c",c);delete.Parameters.AddWithValue("@id",id);return await delete.ExecuteNonQueryAsync(token)==1?NoContent():NotFound();}

    [HttpGet("rounds")]
    public async Task<IActionResult> Rounds([FromQuery]string? sourceType,[FromQuery]string? status,int page=1,int pageSize=20,CancellationToken token=default){if(!Scope(out var c,out var u))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47003","VIEW",token))return Forbid();var permissions=new{create=await Allow(db,"47003","CREATE",token),edit=await Allow(db,"47003","EDIT",token),delete=await Allow(db,"47003","DELETE",token),submit=await Allow(db,"47003","SUBMIT",token)};page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var where="CompanyID=@c AND (@source='' OR SourceType=@source) AND (@status='' OR StatusCode=@status)";var count=new SqlCommand("SELECT COUNT_BIG(1) FROM dbo.TDEVRound WHERE "+where,db);Bind(count,c,sourceType,status);var total=Convert.ToInt64(await count.ExecuteScalarAsync(token));var cmd=new SqlCommand("SELECT EvaluationRoundID,RoundNo,RoundName,SourceType,ReferenceTitleSnapshot,StatusCode,OpenDateTime,CloseDateTime FROM dbo.TDEVRound WHERE "+where+" ORDER BY CreateDate DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY",db);Bind(cmd,c,sourceType,status);cmd.Parameters.AddWithValue("@skip",(page-1)*pageSize);cmd.Parameters.AddWithValue("@take",pageSize);await using var r=await cmd.ExecuteReaderAsync(token);var items=new List<object>();while(await r.ReadAsync(token))items.Add(new{id=r.GetInt64(0),roundNo=r.GetString(1),name=r.GetString(2),sourceType=r.GetString(3),referenceTitle=r.IsDBNull(4)?null:r.GetString(4),status=r.GetString(5),openAt=r.IsDBNull(6)?(DateTime?)null:r.GetDateTime(6),closeAt=r.IsDBNull(7)?(DateTime?)null:r.GetDateTime(7)});return Ok(new{total,page,pageSize,items,permissions});}
    [HttpGet("rounds/{id:long}")]
    public async Task<IActionResult> Round(long id,CancellationToken token){if(!Scope(out var c,out _))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47003","VIEW",token))return Forbid();var head=new SqlCommand("SELECT R.RoundNo,R.RoundName,R.SourceType,R.ReferenceTitleSnapshot,R.StatusCode,R.EvaluationTemplateID,T.TemplateCode,T.TemplateName,R.OpenDateTime,R.CloseDateTime FROM dbo.TDEVRound R JOIN dbo.TDEVTemplate T ON T.EvaluationTemplateID=R.EvaluationTemplateID AND T.CompanyID=R.CompanyID WHERE R.CompanyID=@c AND R.EvaluationRoundID=@id",db);head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@id",id);await using var hr=await head.ExecuteReaderAsync(token);if(!await hr.ReadAsync(token))return NotFound();var result=new{roundNo=hr.GetString(0),name=hr.GetString(1),sourceType=hr.GetString(2),referenceTitle=hr.IsDBNull(3)?null:hr.GetString(3),status=hr.GetString(4),templateId=hr.GetInt64(5),templateCode=hr.GetString(6),templateName=hr.GetString(7),openAt=hr.GetDateTime(8),closeAt=hr.GetDateTime(9)};await hr.CloseAsync();var people=new SqlCommand("SELECT RS.UserID,COALESCE(NULLIF(P.FullName,N''),NULLIF(U.DisplayName,N''),U.Username),U.Username,RS.AssignmentStatus FROM dbo.TDEVRoundRespondent RS JOIN dbo.TDADUser U ON U.UserID=RS.UserID AND U.CompanyID=RS.CompanyID LEFT JOIN dbo.TDADPerson P ON P.PersonID=U.PersonID AND P.CompanyID=U.CompanyID WHERE RS.CompanyID=@c AND RS.EvaluationRoundID=@id ORDER BY U.DisplayName,U.Username",db);people.Parameters.AddWithValue("@c",c);people.Parameters.AddWithValue("@id",id);await using var pr=await people.ExecuteReaderAsync(token);var respondents=new List<object>();while(await pr.ReadAsync(token))respondents.Add(new{id=pr.GetInt64(0),name=pr.GetString(1),username=pr.GetString(2),status=pr.GetString(3)});return Ok(new{document=result,respondents});}
    [HttpDelete("rounds/{id:long}")]
    public async Task<IActionResult> DeleteRound(long id,CancellationToken token){if(!Scope(out var c,out _))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47003","DELETE",token))return Forbid();var cmd=new SqlCommand("DELETE dbo.TDEVRound WHERE CompanyID=@c AND EvaluationRoundID=@id AND StatusCode='DRAFT'",db);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@id",id);return await cmd.ExecuteNonQueryAsync(token)==1?NoContent():Conflict(new{message="ลบรอบประเมินไม่ได้",description="ลบได้เฉพาะร่างที่ยังไม่ส่งอนุมัติ"});}
    async Task<string> TemplateSnapshot(SqlConnection db,SqlTransaction tx,long company,long templateId,CancellationToken token)
    {
        var cmd=new SqlCommand("SELECT Q.EvaluationTemplateQuestionID,Q.QuestionText,Q.QuestionType,Q.IsRequired,Q.SortOrder,O.EvaluationTemplateQuestionOptionID,O.OptionText,O.SortOrder FROM dbo.TDEVTemplateQuestion Q LEFT JOIN dbo.TDEVTemplateQuestionOption O ON O.EvaluationTemplateQuestionID=Q.EvaluationTemplateQuestionID WHERE Q.CompanyID=@c AND Q.EvaluationTemplateID=@template ORDER BY Q.SortOrder,O.SortOrder",db,tx);
        cmd.Parameters.AddWithValue("@c",company);cmd.Parameters.AddWithValue("@template",templateId);
        await using var reader=await cmd.ExecuteReaderAsync(token);
        var questions=new List<Dictionary<string,object?>>();var index=new Dictionary<long,Dictionary<string,object?>>();
        while(await reader.ReadAsync(token)){var id=reader.GetInt64(0);if(!index.TryGetValue(id,out var question)){question=new Dictionary<string,object?>{{"id",$"Q-{id}"},{"text",reader.GetString(1)},{"type",reader.GetString(2)},{"required",reader.GetBoolean(3)},{"sortOrder",reader.GetInt32(4)},{"options",new List<object>()}};index.Add(id,question);questions.Add(question);}if(!reader.IsDBNull(5))((List<object>)question["options"]!).Add(new{id=$"O-{reader.GetInt64(5)}",text=reader.GetString(6),sortOrder=reader.GetInt32(7)});}
        return System.Text.Json.JsonSerializer.Serialize(new{questions});
    }

    [HttpPut("rounds/{id:long}")]
    public async Task<IActionResult> UpdateRound(long id,[FromBody]RoundRequest request,CancellationToken token)
    {
        if(!Scope(out var c,out var u))return Forbid();
        var source=request.SourceType?.Trim().ToUpperInvariant();
        var supportedSources=new[]{"TRAINING_COURSE","TRAINING_INSTRUCTOR","MEETING_ROOM","VENDOR","SERVICE","GENERAL"};
        if(!supportedSources.Contains(source) || string.IsNullOrWhiteSpace(request.Name) || request.CloseAt<=request.OpenAt || (request.RespondentUserIds?.Distinct().Count()??0)==0)
            return BadRequest(new{message="ข้อมูลรอบประเมินไม่ถูกต้อง",description="ระบุชื่อ ช่วงเวลา และผู้ตอบอย่างน้อย 1 คน"});
        await using var db=await Open(token);
        if(!await Allow(db,"47003","EDIT",token))return Forbid();
        var template=new SqlCommand("SELECT COUNT(1) FROM dbo.TDEVTemplate WHERE EvaluationTemplateID=@id AND CompanyID=@c AND IsActive=1 AND SourceType=@source",db);
        template.Parameters.AddWithValue("@id",request.TemplateId);template.Parameters.AddWithValue("@c",c);template.Parameters.AddWithValue("@source",source);
        if(Convert.ToInt32(await template.ExecuteScalarAsync(token))!=1)return BadRequest(new{message="Template ไม่ถูกต้อง",description="Template ต้องอยู่บริษัทเดียวกัน เปิดใช้งาน และตรงกับประเภทงาน"});
        await using var tx=await db.BeginTransactionAsync(token);
        var snapshot=await TemplateSnapshot(db,(SqlTransaction)tx,c,request.TemplateId,token);
        var head=new SqlCommand("UPDATE dbo.TDEVRound SET RoundName=@name,ReferenceTitleSnapshot=@title,EvaluationTemplateID=@template,TemplateSnapshotJson=@snapshot,OpenDateTime=@open,CloseDateTime=@close WHERE CompanyID=@c AND EvaluationRoundID=@id AND SourceType=@source AND StatusCode='DRAFT'",db,(SqlTransaction)tx);
        head.Parameters.AddWithValue("@name",request.Name.Trim());head.Parameters.AddWithValue("@source",source);head.Parameters.AddWithValue("@title",(object?)request.ReferenceTitle?.Trim()??DBNull.Value);head.Parameters.AddWithValue("@template",request.TemplateId);head.Parameters.AddWithValue("@snapshot",snapshot);head.Parameters.AddWithValue("@open",request.OpenAt);head.Parameters.AddWithValue("@close",request.CloseAt);head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@id",id);
        if(await head.ExecuteNonQueryAsync(token)!=1){await tx.RollbackAsync(token);return Conflict(new{message="แก้ไขรอบประเมินไม่ได้",description="แก้ไขได้เฉพาะร่างที่ยังไม่ส่งอนุมัติ"});}
        if(source is "VENDOR" or "GENERAL"){var clear=new SqlCommand("DELETE dbo.TDEVRoundRespondent WHERE CompanyID=@c AND EvaluationRoundID=@id",db,(SqlTransaction)tx);clear.Parameters.AddWithValue("@c",c);clear.Parameters.AddWithValue("@id",id);await clear.ExecuteNonQueryAsync(token);foreach(var userId in request.RespondentUserIds!.Distinct()){var add=new SqlCommand("INSERT dbo.TDEVRoundRespondent(CompanyID,EvaluationRoundID,UserID,EmployeeID) SELECT @c,@round,U.UserID,UE.EmployeeID FROM dbo.TDADUser U LEFT JOIN dbo.TDADUserEmployee UE ON UE.CompanyID=U.CompanyID AND UE.UserID=U.UserID AND UE.IsActive=1 WHERE U.CompanyID=@c AND U.UserID=@user AND U.IsActive=1",db,(SqlTransaction)tx);add.Parameters.AddWithValue("@c",c);add.Parameters.AddWithValue("@round",id);add.Parameters.AddWithValue("@user",userId);await add.ExecuteNonQueryAsync(token);}}
        await tx.CommitAsync(token);return NoContent();
    }

