dAsync(token))questions.Add(new{questionId=ar.GetString(0),average=ar.GetDecimal(1),responses=ar.GetInt64(2)});await ar.CloseAsync();var commentsCmd=new SqlCommand("SELECT TOP(100) AnswerText FROM dbo.TDEVRoundAnswer WHERE CompanyID=@c AND EvaluationRoundSubmissionID IN(SELECT EvaluationRoundSubmissionID FROM dbo.TDEVRoundSubmission WHERE CompanyID=@c AND EvaluationRoundID=@id) AND NULLIF(LTRIM(RTRIM(AnswerText)),N'') IS NOT NULL ORDER BY EvaluationRoundAnswerID",db);commentsCmd.Parameters.AddWithValue("@c",c);commentsCmd.Parameters.AddWithValue("@id",id);await using var commentsReader=await commentsCmd.ExecuteReaderAsync(token);var comments=new List<string>();while(await commentsReader.ReadAsync(token))comments.Add(commentsReader.GetString(0));return Ok(new{name,sourceType=source,referenceTitle=reference,assigned,submitted,isAnonymousThresholdMet=true,questionsJson=snapshot,questions,comments});}

