    [NonAction]
    public async Task<IActionResult> CreateRound([FromBody]RoundRequest request,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();if(request.SourceType?.Trim().ToUpperInvariant() is not("VENDOR" or "GENERAL")||string.IsNullOrWhiteSpace(request.Name)||request.CloseAt<=request.OpenAt||(request.RespondentUserIds?.Distinct().Count()??0)==0)return BadRequest(new{message="ข้อมูลรอบประเมินไม่ถูกต้อง",description="Vendor และ General ต้องระบุชื่อ ช่วงเวลา และผู้ตอบอย่างน้อย 1 คน"});await using var db=await Open(token);if(!await Allow(db,"47003","CREATE",token))return Forbid();var check=new SqlCommand("SELECT COUNT(1) FROM dbo.TDEVTemplate WHERE EvaluationTemplateID=@id AND CompanyID=@c AND IsActive=1",db);check.Parameters.AddWithValue("@id",request.TemplateId);check.Parameters.AddWithValue("@c",c);if(Convert.ToInt32(await check.ExecuteScalarAsync(token))!=1)return NotFound(new{message="ไม่พบ Template",description="Template ต้องอยู่ในบริษัทเดียวกันและเปิดใช้งาน"});await using var tx=await db.BeginTransactionAsync(token);var no="EV"+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+Guid.NewGuid().ToString("N")[..4].ToUpperInvariant();var head=new SqlCommand("INSERT dbo.TDEVRound(CompanyID,RoundNo,RoundName,SourceType,ReferenceTitleSnapshot,EvaluationTemplateID,TemplateSnapshotJson,OpenDateTime,CloseDateTime,CreateBy) VALUES(@c,@no,@name,@source,@title,@template,N'{}',@open,@close,@u); SELECT CONVERT(bigint,SCOPE_IDENTITY());",db,(SqlTransaction)tx);head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@no",no);head.Parameters.AddWithValue("@name",request.Name.Trim());head.Parameters.AddWithValue("@source",request.SourceType.Trim().ToUpperInvariant());head.Parameters.AddWithValue("@title",(object?)request.ReferenceTitle?.Trim()??DBNull.Value);head.Parameters.AddWithValue("@template",request.TemplateId);head.Parameters.AddWithValue("@open",request.OpenAt);head.Parameters.AddWithValue("@close",request.CloseAt);head.Parameters.AddWithValue("@u",u);var id=Convert.ToInt64(await head.ExecuteScalarAsync(token));foreach(var userId in request.RespondentUserIds!.Distinct()){var add=new SqlCommand("INSERT dbo.TDEVRoundRespondent(CompanyID,EvaluationRoundID,UserID,EmployeeID) SELECT @c,@round,U.UserID,UE.EmployeeID FROM dbo.TDADUser U LEFT JOIN dbo.TDADUserEmployee UE ON UE.CompanyID=U.CompanyID AND UE.UserID=U.UserID AND UE.IsActive=1 WHERE U.CompanyID=@c AND U.UserID=@user AND U.IsActive=1",db,(SqlTransaction)tx);add.Parameters.AddWithValue("@c",c);add.Parameters.AddWithValue("@round",id);add.Parameters.AddWithValue("@user",userId);await add.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);return Ok(new{id,roundNo=no});}

    [HttpPost("rounds")]
    public async Task<IActionResult> CreateRoundWithSnapshot([FromBody]RoundRequest request,CancellationToken token)
    {
        if(!Scope(out var c,out var u))return Forbid();
        var source=request.SourceType?.Trim().ToUpperInvariant();
        var respondents=request.RespondentUserIds?.Distinct().ToArray()??[];
        if(source is not("VENDOR" or "GENERAL")||string.IsNullOrWhiteSpace(request.Name)||request.CloseAt<=request.OpenAt||respondents.Length==0)
            return BadRequest(new{message="ข้อมูลรอบประเมินไม่ถูกต้อง",description="Vendor และ General ต้องระบุชื่อ ช่วงเวลา และผู้ตอบอย่างน้อย 1 คน"});
        await using var db=await Open(token);
        if(!await Allow(db,"47003","CREATE",token))return Forbid();
        var check=new SqlCommand("SELECT COUNT(1) FROM dbo.TDEVTemplate WHERE EvaluationTemplateID=@id AND CompanyID=@c AND IsActive=1 AND SourceType=@source",db);
        check.Parameters.AddWithValue("@id",request.TemplateId);check.Parameters.AddWithValue("@c",c);check.Parameters.AddWithValue("@source",source);
        if(Convert.ToInt32(await check.ExecuteScalarAsync(token))!=1)return BadRequest(new{message="Template ไม่ถูกต้อง",description="Template ต้องอยู่บริษัทเดียวกัน เปิดใช้งาน และตรงกับประเภทงาน"});
        await using var tx=(SqlTransaction)await db.BeginTransactionAsync(token);
        var snapshot=await TemplateSnapshot(db,tx,c,request.TemplateId,token);
        var no="EV"+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+Guid.NewGuid().ToString("N")[..4].ToUpperInvariant();
        var head=new SqlCommand("INSERT dbo.TDEVRound(CompanyID,RoundNo,RoundName,SourceType,ReferenceTitleSnapshot,EvaluationTemplateID,TemplateSnapshotJson,OpenDateTime,CloseDateTime,CreateBy) VALUES(@c,@no,@name,@source,@title,@template,@snapshot,@open,@close,@u); SELECT CONVERT(bigint,SCOPE_IDENTITY());",db,tx);
        head.Parameters.AddWithValue("@c",c);head.Parameters.AddWithValue("@no",no);head.Parameters.AddWithValue("@name",request.Name.Trim());head.Parameters.AddWithValue("@source",source);head.Parameters.AddWithValue("@title",(object?)request.ReferenceTitle?.Trim()??DBNull.Value);head.Parameters.AddWithValue("@template",request.TemplateId);head.Parameters.AddWithValue("@snapshot",snapshot);head.Parameters.AddWithValue("@open",request.OpenAt);head.Parameters.AddWithValue("@close",request.CloseAt);head.Parameters.AddWithValue("@u",u);
        var id=Convert.ToInt64(await head.ExecuteScalarAsync(token));
        foreach(var userId in respondents){var add=new SqlCommand("INSERT dbo.TDEVRoundRespondent(CompanyID,EvaluationRoundID,UserID,EmployeeID) SELECT @c,@round,U.UserID,UE.EmployeeID FROM dbo.TDADUser U LEFT JOIN dbo.TDADUserEmployee UE ON UE.CompanyID=U.CompanyID AND UE.UserID=U.UserID AND UE.IsActive=1 WHERE U.CompanyID=@c AND U.UserID=@user AND U.IsActive=1",db,tx);add.Parameters.AddWithValue("@c",c);add.Parameters.AddWithValue("@round",id);add.Parameters.AddWithValue("@user",userId);await add.ExecuteNonQueryAsync(token);}
        await tx.CommitAsync(token);return Ok(new{id,roundNo=no});
    }

