    public async Task<IActionResult> Approve(long id,CancellationToken token){var result=await Move(id,"PENDING_APPROVAL","PUBLISHED","47004","APPROVE",token);if(result is OkObjectResult&&Scope(out var c,out var u)){try{await using var db=await Open(token);await NotifyPublished(db,c,u,id,token);}catch{}}return result;}
    async Task<IActionResult> Move(long id,string from,string to,string screen,string action,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();await using var db=await Open(token);if(!await Allow(db,screen,action,token))return Forbid();var cmd=new SqlCommand("UPDATE dbo.TDEVRound SET StatusCode=@to,"+(to=="PENDING_APPROVAL"?"SubmitDate=SYSUTCDATETIME(),SubmitBy=@u":"ApproveDate=SYSUTCDATETIME(),ApproveBy=@u,PublishDate=SYSUTCDATETIME(),PublishBy=@u")+" WHERE EvaluationRoundID=@id AND CompanyID=@c AND StatusCode=@from",db);cmd.Parameters.AddWithValue("@to",to);cmd.Parameters.AddWithValue("@u",u);cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@from",from);return await cmd.ExecuteNonQueryAsync(token)==1?Ok(new{status=to}):Conflict(new{message="สถานะรอบเปลี่ยนแล้ว",description="กรุณาโหลดข้อมูลล่าสุดก่อนดำเนินการ"});}
    async Task NotifyPublished(SqlConnection db,long company,long actor,long roundId,CancellationToken token){var cmd=new SqlCommand("INSERT dbo.TDADNotification(CompanyID,RecipientUserID,RecipientPersonID,SourceProject,SourceType,SourceID,Title,Message,PayloadJson,IdempotencyKey,StatusCode,SentDate,CreateBy) SELECT @c,RS.UserID,U.PersonID,N'LAOO_EVALUATION',N'EVALUATION_ROUND',@round,N'มีงานประเมินใหม่',N'รอบประเมินได้รับการเผยแพร่แล้ว',NULL,CONCAT(N'EVALUATION-ROUND-',@round,N'-USER-',RS.UserID),N'SENT',SYSUTCDATETIME(),@actor FROM dbo.TDEVRoundRespondent RS JOIN dbo.TDADUser U ON U.CompanyID=RS.CompanyID AND U.UserID=RS.UserID WHERE RS.CompanyID=@c AND RS.EvaluationRoundID=@round AND U.IsActive=1 AND NOT EXISTS(SELECT 1 FROM dbo.TDADNotification N WHERE N.CompanyID=@c AND N.SourceProject=N'LAOO_EVALUATION' AND N.IdempotencyKey=CONCAT(N'EVALUATION-ROUND-',@round,N'-USER-',RS.UserID))",db);cmd.Parameters.AddWithValue("@c",company);cmd.Parameters.AddWithValue("@round",roundId);cmd.Parameters.AddWithValue("@actor",actor);await cmd.ExecuteNonQueryAsync(token);}

