    public async Task<IActionResult> MyRound(long id,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47005","VIEW",token))return Forbid();var cmd=new SqlCommand("SELECT R.RoundName,R.SourceType,R.ReferenceTitleSnapshot,R.TemplateSnapshotJson,R.OpenDateTime,R.CloseDateTime,RS.EvaluationRoundRespondentID FROM dbo.TDEVRound R JOIN dbo.TDEVRoundRespondent RS ON RS.EvaluationRoundID=R.EvaluationRoundID WHERE R.CompanyID=@c AND R.EvaluationRoundID=@id AND RS.UserID=@u AND R.StatusCode='PUBLISHED' AND SYSUTCDATETIME()>=R.OpenDateTime AND SYSUTCDATETIME()<R.CloseDateTime",db);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@u",u);await using var r=await cmd.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))return NotFound(new{message="ไม่พบงานประเมิน",description="งานอาจยังไม่เปิด หมดเวลา หรือไม่ได้มอบหมายให้บัญชีนี้"});return Ok(new{name=r.GetString(0),sourceType=r.GetString(1),referenceTitle=r.IsDBNull(2)?null:r.GetString(2),questionsJson=r.GetString(3),openAt=r.GetDateTime(4),closeAt=r.GetDateTime(5)});}
    [HttpGet("mine/{id:long}/answers")]
    public async Task<IActionResult> MyAnswers(long id,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();await using var db=await Open(token);if(!await Allow(db,"47005","VIEW",token))return Forbid();var cmd=new SqlCommand("SELECT A.QuestionSnapshotID,A.RatingValue,A.AnswerText,A.SelectedOptionJson FROM dbo.TDEVRoundAnswer A JOIN dbo.TDEVRoundSubmission S ON S.EvaluationRoundSubmissionID=A.EvaluationRoundSubmissionID JOIN dbo.TDEVRoundRespondent RS ON RS.EvaluationRoundRespondentID=S.EvaluationRoundRespondentID JOIN dbo.TDEVRound R ON R.EvaluationRoundID=RS.EvaluationRoundID WHERE A.CompanyID=@c AND R.EvaluationRoundID=@id AND RS.UserID=@u AND R.StatusCode='PUBLISHED' AND SYSUTCDATETIME()>=R.OpenDateTime AND SYSUTCDATETIME()<R.CloseDateTime",db);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@id",id);cmd.Parameters.AddWithValue("@u",u);await using var r=await cmd.ExecuteReaderAsync(token);var answers=new List<object>();while(await r.ReadAsync(token)){var optionJson=r.IsDBNull(3)?null:r.GetString(3);answers.Add(new{questionId=r.GetString(0),ratingValue=r.IsDBNull(1)?(int?)null:r.GetByte(1),text=r.IsDBNull(2)?null:r.GetString(2),optionIds=optionJson is null?new List<string>():System.Text.Json.JsonSerializer.Deserialize<List<string>>(optionJson)??new List<string>()});}return Ok(new{answers});}
    [HttpPut("mine/{id:long}/answers")]
    public async Task<IActionResult> SaveAnswers(long id,[FromBody]SubmissionRequest request,CancellationToken token){if(!Scope(out var c,out var u))return Forbid();var answers=request.Answers??[];if(answers.Count==0||answers.Any(a=>string.IsNullOrWhiteSpace(a.QuestionId)))return BadRequest(new{message="คำตอบไม่ครบ",description="กรุณาตอบคำถามที่ระบบกำหนดให้ครบก่อนบันทึก"});await using var db=await Open(token);if(!await Allow(db,"47005","SUBMIT",token))return Forbid();var find=new SqlCommand("SELECT RS.EvaluationRoundRespondentID FROM dbo.TDEVRound R JOIN dbo.TDEVRoundRespondent RS ON RS.EvaluationRoundID=R.EvaluationRoundID WHERE R.CompanyID=@c AND R.EvaluationRoundID=@id AND RS.UserID=@u AND R.StatusCode='PUBLISHED' AND SYSUTCDATETIME()>=R.OpenDateTime AND SYSUTCDATETIME()<R.CloseDateTime",db);find.Parameters.AddWithValue("@c",c);find.Parameters.AddWithValue("@id",id);find.Parameters.AddWithValue("@u",u);var respondent=await find.ExecuteScalarAsync(token);if(respondent is null)return Conflict(new{message="ไม่สามารถบันทึกคำตอบ",description="รอบประเมินปิดแล้วหรือบัญชีนี้ไม่มีสิทธิ์ตอบ"});await using var tx=await db.BeginTransactionAsync(token);var sub=new SqlCommand("SELECT EvaluationRoundSubmissionID FROM dbo.TDEVRoundSubmission WITH(UPDLOCK,HOLDLOCK) WHERE EvaluationRoundRespondentID=@r",db,(SqlTransaction)tx);sub.Parameters.AddWithValue("@r",respondent);var submission=await sub.ExecuteScalarAsync(token);long submissionId;if(submission is null){var add=new SqlCommand("INSERT dbo.TDEVRoundSubmission(CompanyID,EvaluationRoundID,EvaluationRoundRespondentID) OUTPUT INSERTED.EvaluationRoundSubmissionID VALUES(@c,@round,@r)",db,(SqlTransaction)tx);add.Parameters.AddWithValue("@c",c);add.Parameters.AddWithValue("@round",id);add.Parameters.AddWithValue("@r",respondent);submissionId=Convert.ToInt64(await add.ExecuteScalarAsync(token));}else{submissionId=Convert.ToInt64(submission);var del=new SqlCommand("DELETE dbo.TDEVRoundAnswer WHERE EvaluationRoundSubmissionID=@id",db,(SqlTransaction)tx);del.Parameters.AddWithValue("@id",submissionId);await del.ExecuteNonQueryAsync(token);}foreach(var a in answers){var add=new SqlCommand("INSERT dbo.TDEVRoundAnswer(CompanyID,EvaluationRoundSubmissionID,QuestionSnapshotID,RatingValue,AnswerText,SelectedOptionJson) VALUES(@c,@s,@q,@rating,@text,@options)",db,(SqlTransaction)tx);add.Parameters.AddWithValue("@c",c);add.Parameters.AddWithValue("@s",submissionId);add.Parameters.AddWithValue("@q",a.QuestionId);add.Parameters.AddWithValue("@rating",(object?)a.RatingValue??DBNull.Value);add.Parameters.AddWithValue("@text",(object?)a.Text?.Trim()??DBNull.Value);add.Parameters.AddWithValue("@options",a.OptionIds is {Count:>0}?System.Text.Json.JsonSerializer.Serialize(a.OptionIds.Distinct()):DBNull.Value);await add.ExecuteNonQueryAsync(token);}var status=new SqlCommand("UPDATE dbo.TDEVRoundRespondent SET AssignmentStatus='SUBMITTED' WHERE EvaluationRoundRespondentID=@r",db,(SqlTransaction)tx);status.Parameters.AddWithValue("@r",respondent);await status.ExecuteNonQueryAsync(token);await tx.CommitAsync(token);return Ok(new{message="บันทึกคำตอบแล้ว"});}
    bool Scope(out long company,out long user){company=0;user=0;return User.FindFirstValue("user_type")=="COMPANY_USER"&&long.TryParse(User.FindFirstValue("company_id"),out company)&&long.TryParse(User.FindFirstValue("user_id"),out user);}
    async Task<SqlConnection> Open(CancellationToken token){var db=new SqlConnection(configuration.GetConnectionString("LaooDatabase"));await db.OpenAsync(token);return db;}
    async Task<bool> Allow(SqlConnection db,string screen,string action,CancellationToken token){const string sql="""
DECLARE @project bigint=(SELECT ProjectID FROM dbo.TDADProject WHERE ProjectCode='LAOO_EVALUATION' AND IsActive=1);
SELECT CASE WHEN EXISTS(SELECT 1 FROM dbo.TDADUser WHERE CompanyID=@c AND UserID=@u AND IsActive=1 AND IsCompanyAdmin=1)
 OR EXISTS(SELECT 1 FROM dbo.TDADUserPermission UP JOIN dbo.TDADPermission P ON P.PermissionID=UP.PermissionID AND P.ProjectID=@project AND P.IsActive=1 WHERE UP.UserID=@u AND UP.ProjectID=@project AND UP.IsActive=1 AND UP.IsAllowed=1 AND P.ScreenCode=@screen AND P.ActionCode=@action)
 OR EXISTS(SELECT 1 FROM dbo.TDADUserEmployee UE JOIN dbo.TDADEmployee E ON E.EmployeeID=UE.EmployeeID AND E.CompanyID=@c AND E.IsActive=1 JOIN dbo.TDADEmployeeRoleGroup ER ON ER.EmployeeID=UE.EmployeeID AND ER.IsActive=1 JOIN dbo.TDADRoleGroup R ON R.RoleGroupID=ER.RoleGroupID AND R.ScopeType='C' AND R.CompanyID=@c AND R.ProjectID=@project AND R.IsActive=1 JOIN dbo.TDADRoleGroupPermission RP ON RP.RoleGroupID=R.RoleGroupID AND RP.ProjectID=@project AND RP.MenuCode=@screen AND RP.ActionCode=@action AND RP.IsAllowed=1 WHERE UE.CompanyID=@c AND UE.UserID=@u AND UE.IsActive=1 AND ER.EffectiveFrom<=CONVERT(date,SYSUTCDATETIME()) AND (ER.EffectiveTo IS NULL OR ER.EffectiveTo>=CONVERT(date,SYSUTCDATETIME())))
THEN 1 ELSE 0 END;
""";if(!Scope(out var c,out var u))return false;await using var cmd=new SqlCommand(sql,db);cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@u",u);cmd.Parameters.AddWithValue("@screen",screen);cmd.Parameters.AddWithValue("@action",action);return Convert.ToBoolean(await cmd.ExecuteScalarAsync(token));}
    static void Bind(SqlCommand cmd,long c,string? source,string? status){cmd.Parameters.AddWithValue("@c",c);cmd.Parameters.AddWithValue("@source",source?.Trim().ToUpperInvariant()??"");cmd.Parameters.AddWithValue("@status",status?.Trim().ToUpperInvariant()??"");}
}
